using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace DomainConsole.Agent {
 internal static class CacheCleanup31 {
  static bool Allowed(string path){var win=Environment.GetFolderPath(Environment.SpecialFolder.Windows);var originals=new[]{Path.Combine(win,"SoftwareDistribution"),Path.Combine(win,"SoftwareDistribution","Download"),Path.Combine(win,"SoftwareDistribution","EventCache"),Path.Combine(win,"SoftwareDistribution","EventCache.v2"),Path.Combine(win,"System32","catroot2")};var full=Path.GetFullPath(path);return originals.Any(p=>full.StartsWith(p+".DomainConsolePendingDelete_",StringComparison.OrdinalIgnoreCase)&&Path.GetDirectoryName(full).Equals(Path.GetDirectoryName(p),StringComparison.OrdinalIgnoreCase));}
  static void NoLinks(string path){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("Ссылка в отсоединённом кэше; удаление не выполнено");foreach(var child in Directory.EnumerateFileSystemEntries(path)){var attrs=File.GetAttributes(child);if((attrs&FileAttributes.ReparsePoint)!=0)throw new IOException("Ссылка в отсоединённом кэше; удаление не выполнено");if((attrs&FileAttributes.Directory)!=0)NoLinks(child);}}
  public static int Delete(string path){try{if(!Allowed(path))throw new IOException("Недопустимый путь отложенной очистки");if(!Directory.Exists(path))return 0;for(var parent=Path.GetDirectoryName(path);!string.IsNullOrEmpty(parent);parent=Path.GetDirectoryName(parent)){if((File.GetAttributes(parent)&FileAttributes.ReparsePoint)!=0)throw new IOException("Ссылка в родительском пути; удаление не выполнено");}NoLinks(path);Directory.Delete(path,true);return Directory.Exists(path)?1:0;}catch(Exception ex){Console.Error.WriteLine(ex);try{File.WriteAllText(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"DomainConsoleCSharp","cache-delete-error.log"),ex.ToString());}catch{}return 1;}}
  public static void Run(string root){var manifest=Path.Combine(root,"pending-cache-cleanup.jsonl");if(!File.Exists(manifest))return;var json=new JavaScriptSerializer();var keep=new List<string>();var report=new List<string>();try{using(var file=new FileStream(manifest,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){var reader=new StreamReader(file,System.Text.Encoding.UTF8,true,4096,true);var lines=reader.ReadToEnd().Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries);reader.Dispose();int attempted=0;foreach(var line in lines){try{var item=json.Deserialize<Dictionary<string,string>>(line);string path=item["Path"];if(!Allowed(path))throw new IOException("Недопустимый путь в реестре очистки");if(!Directory.Exists(path))continue;if(attempted++>=4){keep.Add(line);continue;}var start=new ProcessStartInfo(typeof(CacheCleanup31).Assembly.Location,"cache-delete \""+path+"\""){UseShellExecute=false,CreateNoWindow=true};using(var p=Process.Start(start)){if(!p.WaitForExit(30000)){p.Kill();p.WaitForExit();keep.Add(line);report.Add(path+": лимит удаления 30 секунд; остатки сохранены");}else if(p.ExitCode!=0){keep.Add(line);report.Add(path+": остатки не удалены; причина в cache-delete журнале/ошибке дочернего процесса");}else report.Add(path+": удалён старый кэш");}}catch(Exception ex){keep.Add(line);report.Add(ex.Message);}}file.Position=0;file.SetLength(0);using(var writer=new StreamWriter(file,new System.Text.UTF8Encoding(true),4096,true)){foreach(var line in keep)writer.WriteLine(line);}}File.WriteAllText(Path.Combine(root,"cache-cleanup-last.log"),DateTime.UtcNow.ToString("o")+Environment.NewLine+string.Join(Environment.NewLine,report));}catch(Exception ex){try{File.WriteAllText(Path.Combine(root,"cache-cleanup-last.log"),ex.ToString());}catch{}}}
 }
}
